    {"id":"ga_009","name":"Sinquerim Beach","state":"Goa","region":"North Goa","lat":15.5016,"lon":73.7741,"description":"A beautiful beach at the base of the 17th-century Fort Aguada. The fort's lighthouse is the oldest in Asia (1612). Home to Goa's top heritage hotels including Taj Fort Aguada.","tags":["fort","lighthouse","heritage","luxury","history"],"best_season":"Nov–Mar"},
