    {"id":"an_007","name":"Wandoor Beach","state":"Andaman and Nicobar","region":"Port Blair","lat":11.5867,"lon":92.6274,"description":"Gateway to the Mahatma Gandhi Marine National Park. Glass-bottom boat rides reveal pristine coral reefs with 50 varieties of coral. Sunset cruises are popular here.","tags":["marine_park","coral","glass_bottom_boat","eco","sunset"],"best_season":"Oct–May"},

