def find_beach(name: str):
    q = name.lower().strip()
    # Exact match first
    for b in BEACHES:
        if b["name"].lower() == q:
            return b
    # Partial match
    for b in BEACHES:
        if q in b["name"].lower() or b["name"].lower() in q:
            return b
    return None


def beaches_by_state(state: str) -> list:
    q = state.lower().strip()
    return [b for b in BEACHES if q in b["state"].lower() or q in b["region"].lower()]


def get_all_states() -> list:
    return sorted(set(b["state"] for b in BEACHES))


def get_beach_by_id(beach_id: str):
    return next((b for b in BEACHES if b["id"] == beach_id), None)


if __name__ == "__main__":
    print(f"Total beaches: {len(BEACHES)}")
    for state in get_all_states():
        count = len(beaches_by_state(state))
        print(f"  {state}: {count}")
